import { CompileCommandError } from "../errors.js";

// DS-042: shell-quoted argument tokeniser for the LLVM JSON Compilation
// Database Format `command` field.
//
// Specification: https://clang.llvm.org/docs/JSONCompilationDatabase.html
//
//   "Parameters use shell quoting and shell escaping of quotes, with `"` and
//    `\` being the only special characters. Shell expansion is not supported."
//
// This narrower-than-POSIX rule matters because real cross-platform
// compile_commands.json files - especially those generated by CMake's Ninja
// generator on Windows - use backslash as the path separator. A POSIX shell
// tokeniser would greedily eat those backslashes and turn
// `C:\msys64\ucrt64\bin\c++.exe` into `C:msys64ucrt64binc++.exe`.
//
// Per the spec, the rule is:
//   - `\"` -> literal `"` (regardless of quote context)
//   - `\\` -> literal `\` (regardless of quote context)
//   - `\<other>` -> preserved verbatim (both characters kept)
//   - `"<...>"` is a quoted region; whitespace inside it does not split tokens
//   - Whitespace (space, tab, newline, CR) outside quotes splits tokens
//   - Single quotes are NOT special per the spec, but Dossier preserves the
//     POSIX-style single-quote-as-literal-region behaviour for backward
//     compatibility with non-LLVM databases that use it. Inside a single-
//     quoted region, even backslashes are literal.

export function tokenizeShellCommand(command: string): string[] {
  const tokens: string[] = [];
  let current = "";
  let hasContent = false;
  let inSingle = false;
  let inDouble = false;
  let i = 0;

  const pushToken = () => {
    if (hasContent) {
      tokens.push(current);
      current = "";
      hasContent = false;
    }
  };

  while (i < command.length) {
    const ch = command[i]!;

    if (inSingle) {
      if (ch === "'") {
        inSingle = false;
      } else {
        current += ch;
        hasContent = true;
      }
      i++;
      continue;
    }

    if (inDouble) {
      if (ch === "\\" && i + 1 < command.length) {
        const next = command[i + 1]!;
        // LLVM spec: only `"` and `\` are special characters.
        if (next === '"' || next === "\\") {
          current += next;
          hasContent = true;
          i += 2;
          continue;
        }
        // Any other backslash sequence is preserved verbatim. This is the
        // critical rule for Windows paths inside quoted -I/-D values like
        // `"-IC:\Program Files\sdk\include"`.
        current += ch;
        hasContent = true;
        i++;
        continue;
      }
      if (ch === '"') {
        inDouble = false;
      } else {
        current += ch;
        hasContent = true;
      }
      i++;
      continue;
    }

    if (ch === " " || ch === "\t" || ch === "\n" || ch === "\r") {
      pushToken();
      i++;
      continue;
    }

    if (ch === "'") {
      inSingle = true;
      hasContent = true;
      i++;
      continue;
    }

    if (ch === '"') {
      inDouble = true;
      hasContent = true;
      i++;
      continue;
    }

    if (ch === "\\" && i + 1 < command.length) {
      const next = command[i + 1]!;
      // LLVM spec: outside quotes, only `"` and `\` are special.
      if (next === '"' || next === "\\") {
        current += next;
        hasContent = true;
        i += 2;
        continue;
      }
      // Any other backslash sequence is preserved verbatim. This is the
      // critical rule for Windows path separators outside quotes, like
      // `C:\msys64\ucrt64\bin\c++.exe`.
      current += ch;
      hasContent = true;
      i++;
      continue;
    }

    current += ch;
    hasContent = true;
    i++;
  }

  if (inSingle || inDouble) {
    throw new CompileCommandError(
      "unterminated quoted string in shell command"
    );
  }

  pushToken();
  return tokens;
}
